def roles_to_slots(apps, schema_editor):
    """
    What a model brought itself (the machines fitted to its set, not the
    station's) becomes a slot of its station, and those fittings fill them.
    """
    Station = apps.get_model("systems", "Station")
    StationSlot = apps.get_model("systems", "StationSlot")
    Installation = apps.get_model("systems", "Installation")
    for station in Station.objects.all():
        per_set = {}
        for inst in (
            Installation.objects.filter(test_set__station=station, removed_at__isnull=True, role__isnull=False)
            .select_related("role", "component").order_by("role__position", "id")
        ):
            per_set.setdefault(inst.test_set_id, []).append(inst)
        needed, order, required = {}, {}, {}
        for fittings in per_set.values():
            counts = {}
            for inst in fittings:
                category = inst.component.category_id
                counts[category] = counts.get(category, 0) + 1
                order.setdefault(category, inst.role.position)
                required[category] = required.get(category, False) or inst.role.is_required
            for category, count in counts.items():
                needed[category] = max(needed.get(category, 0), count)
        slots, position = {}, 0
        for category in sorted(needed, key=lambda c: order[c]):
            for _ in range(needed[category]):
                position += 1
                slots.setdefault(category, []).append(StationSlot.objects.create(
                    station=station, category_id=category, is_required=required[category], position=position,
                ))
        for fittings in per_set.values():
            used = {}
            for inst in fittings:
                category = inst.component.category_id
                index = used.get(category, 0)
                used[category] = index + 1
                inst.slot = slots[category][index]
                inst.save(update_fields=["slot"])


